import React from 'react';
import Slider from 'react-slick';
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";
import '../styles/ClientesCarrusel.css';
import { useNavigate } from 'react-router-dom';

const clientes = [
  { nombre: 'Home & Care', img: '/clientes/homecare.png' },
  { nombre: 'NT Line', img: '/clientes/ntline.png' },
  { nombre: 'Kbina', img: '/clientes/kbina.png' },
  { nombre: 'Pronabell', img: '/clientes/pronabell.png' },
  { nombre: 'Edificio Corporativo', img: '/clientes/edificio-corporativo.png' },
];

const ClientesCarrusel = () => {
const navigate = useNavigate();
  const settings = {
    dots: false,
    infinite: true,
    speed: 500,
    slidesToShow: 4,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 2500,
    responsive: [
      { breakpoint: 1024, settings: { slidesToShow: 3 } },
      { breakpoint: 600, settings: { slidesToShow: 2 } },
      { breakpoint: 480, settings: { slidesToShow: 1 } },
    ]
  };

  return (
    <div className="clientes-section">
      <h4 className="clientes-sub">Nuestro Clientes</h4>
      <h2 className="clientes-title">Empresas que confían en nosotros</h2>
      <Slider {...settings} className="clientes-carrusel">
        {clientes.map((cliente, idx) => (
          <div key={idx} className="cliente-logo">
            <img src={cliente.img} alt={cliente.nombre} />
          </div>
        ))}
      </Slider>
      <button className="clientes-btn" onClick={() => navigate('/contacto')}>
  ¡SOLICITA UNA ASESORÍA AHORA!
</button>
      <div className="clientes-footer">© 2025 PHG Soluciones Contables.</div>
    </div>
  );
};

export default ClientesCarrusel;
